/* Lot 112: var() of the animated element in color and background-color keyframes (generated by scripts/lot112_gen.py; expectations from scripts/lot112_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[4096];
static char g_o[1024];

static void prep(const char *css, int ms) {
    wf_site_set_time(ms);
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><p id=i>i</p></div><p id=q>q</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), 640, 480, 0, 0));
    wf_site_set_time(0);
}

static const char *style_of(const char *id) {
    int i;
    g_o[0] = 0;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) wf_site_style_attr(&g_d, g_d.node[i].start, g_o, (int)sizeof(g_o));
    return g_o;
}

static void test_l112_ckf_0(void) {
    prep("@keyframes k { 25% { background-color: #ffffff } 50% { background-color: #ffffff } } body { --n: 0 } body { --c: 12px } #o { --c: #00ff00 } body { --d: #80808080 } #o { background-color: #000000; animation: k 2s linear }", 1216);
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#c8c8c8\"", style_of("o"));
    TEST_ASSERT_EQUAL(1, g_d.col_animated);
    prep("@keyframes k { from { color: var(--d, var(--c)) } 25% { color: #000000 } } #o { animation: k 1s ease-in } body { --c: teal } body { --n: 255 }", 500);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#000000\"", style_of("o"));
    TEST_ASSERT_EQUAL(1, g_d.col_animated);
    prep("@keyframes k { from { background-color: var(--d, var(--c)) } 50% { background-color: var(--d, var(--c)) } to { background-color: var(--zz) } } #o { background-color: #204060; animation: k 1s linear 250ms }", 1200);
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#204060\"", style_of("o"));
    TEST_ASSERT_EQUAL(0, g_d.col_animated);
    prep("@keyframes k { from { color: #ffffff } 25% { color: var(--c) !important } 50% { color: #000000 } } body { --d: 12px } body { --n: 128 } body { --c: #336699 } #o { color: #204060; animation: k 1s ease-in }", 750);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#0a141e\"", style_of("o"));
    TEST_ASSERT_EQUAL(1, g_d.col_animated);
    prep("@keyframes k { 50% { background-color: var(--d) } } #o { animation: k 1s ease-in } body { --d: nosuch } #o { --d: nosuch } #o { --n: 1px }", 564);
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL(0, g_d.col_animated);
    prep("@keyframes k { 25% { color: var(--zz, #102030) } 100% { color: var(--c) } } #o { --d: nosuch } #o { animation: k 1s linear } #o { --n: 0 } body { --c: #ff0000 }", 1200);
    TEST_ASSERT_EQUAL_STRING("", style_of("o"));
    TEST_ASSERT_EQUAL(0, g_d.col_animated);
    prep("@keyframes k { 0% { background-color: #000000 } 25% { background-color: var(--zz) } 50% { background-color: var(--c, #00ff00) } } #o { --c: #0000ff } body { --d: white } #o { --n: 255 } #o { --d: #ff0000 } #o { background-color: rgb(0 0 255); animation: k 1s ease-in } body { --n: 1px }", 250);
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#000050\"", style_of("o"));
    TEST_ASSERT_EQUAL(1, g_d.col_animated);
    prep("@keyframes k { 25% { color: var(--c) } 50% { color: var(--c)var(--d) } 100% { color: var(--c) !important } } #o { --d: 12px } #o { color: #000000; animation: k 1s ease-in }", 250);
    TEST_ASSERT_EQUAL_STRING(" style=\"color:#000000\"", style_of("o"));
    TEST_ASSERT_EQUAL(0, g_d.col_animated);
    prep("@keyframes k { from { background-color: var(--c) } 25% { background-color: var(--c)var(--d) } } #o { --c: transparent } #o { animation: k 1s linear } body { --d: transparent } body { --c: 12px }", 961);
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#00000000\"", style_of("o"));
    TEST_ASSERT_EQUAL(1, g_d.col_animated);
    prep("@keyframes k { 25% { background-color: #ffffff } 50% { background-color: var(--c)var(--d) } } body { --c: #80808080 } body { --n: 1px } #o { --n: 1px } body { --d: nosuch } #o { --d: #0000ff } #o { background-color: rgb(0 0 255); animation: k 1s linear 250ms }", 0);
    TEST_ASSERT_EQUAL_STRING(" style=\"background-color:#0000ff\"", style_of("o"));
    TEST_ASSERT_EQUAL(0, g_d.col_animated);
}

